		'permission_callback' => function () { return current_user_can('manage_options'); },
		'callback' => function () {
			global $wpdb;
			$c = get_post_field('post_content', 10706); $o = $c;
			$c = str_replace('<strong>Diumumkan saat peluncuran</strong>', '<strong>TBA (To Be Announced)</strong>', $c, $a);
			$c = preg_replace('#Harga resmi Indonesia((?:\s|<[^>]+>)*)diumumkan saat peluncuran#', 'Harga: <strong>TBA (To Be Announced)</strong>,$1diumumkan resmi saat peluncuran', $c, -1, $b);
			$i = stripos($c, 'Harga resmi Indonesia');
			$out = array('a' => $a, 'b' => $b, 'ctx' => $i === false ? null : substr($c, $i - 50, 250));
			if ($c !== $o) { $wpdb->update($wpdb->posts, array('post_content' => $c), array('ID' => 10706)); clean_post_cache(10706); $out['saved'] = 1; }
			wp_cache_flush();
			return $out;
		},
	));
});
